//! # `SKNet` prefabs

// The prefabs and the stage table between the `gen_resnet_kin_prefabs`
// markers are generated by `tools/gen_resnet_kin_prefabs.py` from timm's own
// `sknet.py` entrypoints and models; edit the script, not them.

use alloc::{
    vec,
    vec::Vec,
};

use crate::{
    data::pretrained::{
        PrefabTable,
        Prefabs,
    },
    kits::images::classification::{
        resnet::{
            BottleneckPolicyConfig,
            ResNetContractConfig,
        },
        sknet::SKNetContractConfig,
    },
};

impl SKNetContractConfig {
    /// An `SKNet` of 1000 classes: `ResNet` stages of `layers` units, basic
    /// blocks or, under `bottleneck`, bottlenecks of `base_width` per 64
    /// planes in `cardinality` groups; the attention `rd_ratio` of the mixer
    /// in `rd_divisor`s, the input split across the paths under
    /// `split_input`.
    fn sknet(
        layers: Vec<usize>,
        bottleneck: bool,
        base_width: usize,
        cardinality: usize,
        rd_ratio: f64,
        rd_divisor: usize,
        split_input: bool,
    ) -> Self {
        let resnet = ResNetContractConfig::new(layers, 1000);
        let resnet = match bottleneck {
            true => resnet.with_bottleneck_policy(Some(
                BottleneckPolicyConfig::new()
                    .with_base_width(base_width)
                    .with_cardinality(cardinality),
            )),
            false => resnet,
        };
        Self::new(resnet)
            .with_rd_ratio(rd_ratio)
            .with_rd_divisor(rd_divisor)
            .with_split_input(split_input)
    }

    // gen_resnet_kin_prefabs: begin fns
    /// The `skresnet18` prefab: `SKNet` `skresnet18`; basic blocks, an
    /// attention of 0.125 of the channels in 16s, the input split across the
    /// paths.
    pub fn skresnet18() -> Self {
        Self::sknet(vec![2, 2, 2, 2], false, 64, 1, 0.125, 16, true)
    }

    /// The `skresnet34` prefab: `SKNet` `skresnet34`; basic blocks, an
    /// attention of 0.125 of the channels in 16s, the input split across the
    /// paths.
    pub fn skresnet34() -> Self {
        Self::sknet(vec![3, 4, 6, 3], false, 64, 1, 0.125, 16, true)
    }

    /// The `skresnext50_32x4d` prefab: `SKNet` `skresnext50_32x4d`; bottlenecks
    /// of 32 groups of 4 per 64 planes, an attention of 0.0625 of the channels
    /// in 32s.
    pub fn skresnext50_32x4d() -> Self {
        Self::sknet(vec![3, 4, 6, 3], true, 4, 32, 0.0625, 32, false)
    }
    // gen_resnet_kin_prefabs: end fns
}

/// The `SKNet` geometries by name, timm's architecture names: a
/// [`SKNetContractConfig`] of 1000 classes for every architecture of
/// timm's `sknet.py` with hub weights.
///
/// A prefab has no weights: a timm row takes the classes from its
/// `config.json`.
impl Prefabs for SKNetContractConfig {
    const PREFABS: PrefabTable<Self> = &[
        // gen_resnet_kin_prefabs: begin table
        ("skresnet18", Self::skresnet18),
        ("skresnet34", Self::skresnet34),
        ("skresnext50_32x4d", Self::skresnext50_32x4d),
        // gen_resnet_kin_prefabs: end table
    ];
    const PREFAB_TABLE: &'static str = "sknet";
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        blocks::{
            conv::ConvBlock2dMeta,
            images::models::conv_net::ConvChainMeta,
        },
        burner::module::ToStructureConfig,
    };

    /// Each architecture as timm builds it: its stem's conv widths, and each
    /// stage's `(depth, width, mixer width)`, read from timm's modules (the
    /// mixer width is the first `1x1`'s output).
    #[allow(clippy::type_complexity)]
    const TIMM_STAGES: &[(&str, &[usize], [(usize, usize, usize); 4])] = &[
        // gen_resnet_kin_prefabs: begin stages
        (
            "skresnet18",
            &[64],
            [(2, 64, 64), (2, 128, 128), (2, 256, 256), (2, 512, 512)],
        ),
        (
            "skresnet34",
            &[64],
            [(3, 64, 64), (4, 128, 128), (6, 256, 256), (3, 512, 512)],
        ),
        (
            "skresnext50_32x4d",
            &[64],
            [
                (3, 256, 128),
                (4, 512, 256),
                (6, 1024, 512),
                (3, 2048, 1024),
            ],
        ),
        // gen_resnet_kin_prefabs: end stages
    ];

    /// Every prefab's stem and stages are timm's.
    #[test]
    fn test_prefab_stages_are_timms() {
        assert_eq!(TIMM_STAGES.len(), SKNetContractConfig::prefab_names().len());
        for (name, stem, stages) in TIMM_STAGES {
            let structure = SKNetContractConfig::expect_prefab(name)
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let ours: Vec<_> = structure
                .stem
                .convs
                .iter()
                .map(|c| c.out_channels())
                .collect();
            assert_eq!(&ours, stem, "{name}: the stem");
            let ours: Vec<_> = structure
                .stages
                .iter()
                .map(|s| {
                    let unit = &s.units[0];
                    (
                        s.units.len(),
                        unit.out_channels(),
                        unit.convs[0].out_channels(),
                    )
                })
                .collect();
            assert_eq!(ours, stages, "{name}");
        }
    }
}
